    edges_to_add = []
    for i in range(len(articulation_points)):
        for j in range(i + 1, len(articulation_points)):
            if nx.is_edge(G, articulation_points[i], articulation_points[j]):
                edges_to_add.append((articulation_points[i], articulation_points[j]))
            else:
                edges_to_add.append((articulation_points[i], articulation_points[j]))
    print('The minimum set of edges to add is:', edges_to_add)
    print([edges_to_add])"}

